<?php
namespace App\Jobs; use App\Models\IntegrationDelivery; use App\Services\DependencyClient; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Queue\Queueable; use Illuminate\Support\Facades\Log;
final class DeliverTicketNotification implements ShouldQueue { use Queueable; public int $tries=3; public array $backoff=[1,2]; public function __construct(public int $deliveryId,public string $jobId,public string $correlationId){} public function handle(DependencyClient $client):void{$delivery=IntegrationDelivery::findOrFail($this->deliveryId);$delivery->increment('attempts');Log::info('job.started',['operation'=>'ticket.notification','job_id'=>$this->jobId,'correlation_id'=>$this->correlationId,'organization_id'=>$delivery->organization_id,'attempt'=>$delivery->attempts]);try{$provider=$client->deliver(['ticketId'=>$delivery->ticket_id,'event'=>'ticket.created'],$this->correlationId);$delivery->update(['status'=>'delivered','provider_id'=>$provider,'error_category'=>null]);Log::info('job.completed',['job_id'=>$this->jobId,'correlation_id'=>$this->correlationId]);}catch(\Throwable $e){$delivery->update(['status'=>'retrying','error_category'=>'dependency_failure']);throw $e;}} public function failed(?\Throwable $e):void{IntegrationDelivery::whereKey($this->deliveryId)->update(['status'=>'failed','error_category'=>'retry_exhausted']);Log::error('job.failed',['job_id'=>$this->jobId,'correlation_id'=>$this->correlationId,'error_category'=>'retry_exhausted']);}}
